import numpy as np
import sys

try:
    data = np.load("/root/pred_dyn_masks.npz")
    print("Files in archive:", data.files)
    if "shape" in data:
        print("Shape:", data["shape"])
    else:
        print("Missing 'shape' key")

    # Check for expected keys for a few frames
    # Based on json, we have samples at 0, 10, 20, ... 200
    # There are 21 samples (0 to 200 step 10).

    samples = list(range(0, 201, 10)) # 0, 10, ..., 200

    for idx in samples[:3]: # Check first 3
        keys = [f"f_{idx}_data", f"f_{idx}_indices", f"f_{idx}_indptr"]
        for k in keys:
            if k not in data:
                print(f"Missing key: {k}")
            else:
                arr = data[k]
                print(f"{k}: shape={arr.shape}, dtype={arr.dtype}")

except Exception as e:
    print(f"Error: {e}")

